const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const beira = ee.Geometry.Point([34.8386, -19.8333]); // Beira, Mozambique
  const manga = ee.Geometry.Point([35.3833, -15.0333]); // Manga, Mozambique
  const locations = ee.FeatureCollection([ee.Feature(beira), ee.Feature(manga)]);

  const date1 = '2019-03-09';
  const date2 = '2019-03-24';

  // 2. Data Acquisition - VIIRS Nighttime Lights
  const col1 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate(date1, ee.Date(date1).advance(1, 'day'))
    .select('avg_rad');

  const col2 = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG')
    .filterDate(date2, ee.Date(date2).advance(1, 'day'))
    .select('avg_rad');

  // Check if collections have data
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`March 9 Images: ${size1}, March 24 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const img1 = col1.first();
  const img2 = col2.first();

  // 3. Processing - Extract radiance values
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: locations,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: locations,
    scale: 1000,
    maxPixels: 1e9
  });

  const rad1 = stats1.get('avg_rad').getInfo();
  const rad2 = stats2.get('avg_rad').getInfo();

  // Check for valid pixels
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: locations,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: locations,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log(`March 9 Radiance: ${rad1?.toFixed(4)}, Pixels: ${count1}`);
  console.log(`March 24 Radiance: ${rad2?.toFixed(4)}, Pixels: ${count2}`);

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (rad1 === null || rad2 === null || isNaN(rad1) || isNaN(rad2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare radiance values - lower on March 24 means rad2 < rad1
  if (rad2 < rad1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
